-- ============================================================
-- RBAC 种子数据：3 个内置角色 + 18 个权限点 + 角色权限分配
-- + 默认根部门 + 现有 users.role 映射到 role_id
-- 全部 INSERT IGNORE，保证幂等（重复执行不报错）
-- ============================================================

-- 固定 UUID（便于种子引用）：
--   admin    = 00000000-0000-0000-0000-000000000001
--   operator = 00000000-0000-0000-0000-000000000002
--   viewer   = 00000000-0000-0000-0000-000000000003
--   根部门   = 00000000-0000-0000-0000-100000000001
--   权限点   = 20000000-0000-0000-0000-00000000000X

SET @now = UTC_TIMESTAMP();

-- ---- 默认根部门 ----
INSERT IGNORE INTO departments (id, name, parent_id, sort_order, enabled, created_at, updated_at)
VALUES ('00000000-0000-0000-0000-100000000001', '总公司', NULL, 0, 1, @now, @now);

-- ---- 三个内置角色 ----
INSERT IGNORE INTO roles (id, name, display_name, description, enabled, built_in, created_at, updated_at) VALUES
('00000000-0000-0000-0000-000000000001', 'admin',    '管理员', '系统最高权限，拥有所有操作能力', 1, 1, @now, @now),
('00000000-0000-0000-0000-000000000002', 'operator', '运维',   '日常运维操作，不含角色与系统配置管理', 1, 1, @now, @now),
('00000000-0000-0000-0000-000000000003', 'viewer',   '只读',   '仅查看权限，不可执行任何写操作',     1, 1, @now, @now);

