-- ---- 现有用户 role 字符串 → role_id 回填 ----
UPDATE users SET role_id = CASE role
    WHEN 'admin'    THEN '00000000-0000-0000-0000-000000000001'
    WHEN 'operator' THEN '00000000-0000-0000-0000-000000000002'
    ELSE '00000000-0000-0000-0000-000000000003'
END
WHERE role_id IS NULL;